"""Real GnuPG keys for tests."""

from __future__ import annotations

import pathlib
import shutil
import subprocess
import tempfile


def make_key(
    _unused: pathlib.Path,
    *uids: str,
    passphrase: str = "",
    expires: str = "never",
    faked_time: str | None = None,
) -> tuple[str, str]:
    """``(armored private key, armored public key)`` generated by real GnuPG."""
    # Short path: GnuPG's agent socket lives in the home and macOS temp paths are too long.
    home = pathlib.Path(tempfile.mkdtemp(prefix="gk-", dir="/tmp"))
    home.chmod(0o700)
    base = ["gpg", "--homedir", str(home), "--batch", "--pinentry-mode", "loopback"]
    if faked_time:
        base += ["--faked-system-time", faked_time]
    generate = [
        *base,
        "--passphrase",
        passphrase,
        "--quick-generate-key",
        uids[0],
        "ed25519",
        "sign",
        expires,
    ]
    subprocess.run(generate, check=True, capture_output=True)
    fingerprint = (
        subprocess.run(
            ["gpg", "--homedir", str(home), "--list-keys", "--with-colons"],
            check=True,
            capture_output=True,
            text=True,
        )
        .stdout.split("fpr:::::::::")[1]
        .split(":")[0]
    )
    for extra in uids[1:]:
        subprocess.run(
            [*base, "--passphrase", passphrase, "--quick-add-uid", fingerprint, extra],
            check=True,
            capture_output=True,
        )
    private = subprocess.run(
        [*base, "--passphrase", passphrase, "--armor", "--export-secret-keys", fingerprint],
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    public = subprocess.run(
        [*base, "--armor", "--export", fingerprint], check=True, capture_output=True, text=True
    ).stdout
    subprocess.run(["gpgconf", "--homedir", str(home), "--kill", "all"], capture_output=True)
    shutil.rmtree(home, ignore_errors=True)
    return private, public
